rule my_test_rule {
   priority 700
   when HTTP_REQUEST {
      HTTP::header insert ORIG_CLIENT_IP [IP::remote_addr]
   }
   priority 400
   when CLIENT_ACCEPTED {
      log "Client [IP::remote_addr] connected"
   }
   when HTTP_REQUEST {
      log "Requested URI: [HTTP::host][HTTP::uri]"
   }
}

